#include <bits/stdc++.h>
using namespace std;

typedef long long ll;

int N, M, K;
vector<ll> P;
vector<int> parent;
vector<ll> sum;
vector<int> head, tail, nxt;
vector<ll> ans;

int find(int x) {
    int root = x;
    while (parent[root] != root) {
        root = parent[root];
    }
    while (x != root) {
        int next = parent[x];
        parent[x] = root;
        x = next;
    }
    return root;
}

void freeze(int r) {
    int cur = head[r];
    while (cur != -1) {
        ans[cur] = sum[r];
        cur = nxt[cur];
    }
    head[r] = tail[r] = -1;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    cin >> N >> M;
    K = N * M;
    P.resize(K);
    for (int i = 0; i < N; ++i) {
        for (int j = 0; j < M; ++j) {
            cin >> P[i * M + j];
        }
    }

    vector<int> order(K);
    iota(order.begin(), order.end(), 0);
    sort(order.begin(), order.end(), [&](int a, int b) {
        if (P[a] != P[b]) return P[a] < P[b];
        return a < b;
    });

    parent.assign(K, -1);
    sum.assign(K, 0);
    head.assign(K, -1);
    tail.assign(K, -1);
    nxt.assign(K, -1);
    ans.assign(K, 0);

    for (int id : order) {
        int i = id / M;
        int j = id % M;
        parent[id] = id;
        sum[id] = P[id];
        head[id] = id;
        tail[id] = id;
        nxt[id] = -1;

        int roots[4];
        int cnt = 0;

        auto add_root = [&](int u) {
            if (parent[u] != -1) {
                int r = find(u);
                bool found = false;
                for (int k = 0; k < cnt; ++k) {
                    if (roots[k] == r) {
                        found = true;
                        break;
                    }
                }
                if (!found) roots[cnt++] = r;
            }
        };

        if (i > 0) add_root((i - 1) * M + j);
        if (i < N - 1) add_root((i + 1) * M + j);
        if (j > 0) add_root(i * M + (j - 1));
        if (j < M - 1) add_root(i * M + (j + 1));

        ll new_sum = P[id];
        for (int k = 0; k < cnt; ++k) {
            int r = roots[k];
            new_sum += sum[r];
            if (sum[r] >= P[id]) {
                // strong component: merge its active list
                if (head[id] == -1) {
                    head[id] = head[r];
                    tail[id] = tail[r];
                } else {
                    nxt[tail[id]] = head[r];
                    tail[id] = tail[r];
                }
            } else {
                // weak component: freeze it
                freeze(r);
            }
            parent[r] = id;
        }
        sum[id] = new_sum;
    }

    for (int i = 0; i < K; ++i) {
        if (parent[i] == i) {
            freeze(i);
        }
    }

    for (int i = 0; i < N; ++i) {
        for (int j = 0; j < M; ++j) {
            if (j > 0) cout << ' ';
            cout << ans[i * M + j];
        }
        cout << '\n';
    }

    return 0;
}
